from pathlib import Path

def list_text_files(directory):
    root = Path(directory)
    return sorted(path.name for path in root.iterdir()
                  if path.is_file() and path.suffix == '.txt')

# Sorting the names makes the result independent of filesystem iteration order.
# Directories are excluded even when their names end in the expected suffix.

def attempt_three_times(operation):
    last_error = None
    for attempt in range(3):
        try:
            return operation()
        except TimeoutError as error:
            last_error = error
    raise last_error

# Only timeout errors are retried. Other failures propagate immediately,
# allowing the caller to distinguish a temporary delay from an invalid request.

def overlaps(a_start, a_end, b_start, b_end):
    if a_start > a_end or b_start > b_end:
        raise ValueError('reversed interval')
    return max(a_start, b_start) < min(a_end, b_end)

# Half-open intervals that merely touch at an endpoint do not overlap.
assert overlaps(1, 4, 3, 7)
assert not overlaps(1, 3, 3, 5)

