from dataclasses import dataclass

@dataclass(frozen=True)
class Point:
    x: float
    y: float

def squared_distance(a, b):
    return (a.x - b.x) ** 2 + (a.y - b.y) ** 2

origin = Point(0.0, 0.0)
assert squared_distance(origin, Point(3.0, 4.0)) == 25.0

